/* Push only: never cache purchasing pages or authenticated data. */
self.addEventListener('push',event=>{event.waitUntil((async()=>{let payload;try{payload=event.data?.json()}catch{return}if(!payload)return;const base=self.registration.scope;await self.registration.showNotification(payload.title||'Kedai UPU',{body:payload.body||'Ada pembaruan baru.',icon:new URL('assets/logo.png',base).href,badge:new URL('assets/logo.png',base).href,tag:payload.tag,data:payload.data||{}});for(const client of await self.clients.matchAll({type:'window',includeUncontrolled:true})){if(client.url.startsWith(base))client.postMessage({type:'upu-push-refresh'})}})())});
self.addEventListener('notificationclick',event=>{event.notification.close();event.waitUntil((async()=>{const data=event.notification.data||{},url=new URL(self.registration.scope);if(data.screen==='chat'&&/^[A-Za-z0-9_-]{1,120}$/.test(data.supplier_id||'')){url.searchParams.set('push_chat',data.supplier_id)}else if(data.screen==='users')url.searchParams.set('push_users','1');else if(/^[0-9a-f-]{36}$/i.test(data.order_id||''))url.searchParams.set('push_order',data.order_id);const windows=await self.clients.matchAll({type:'window',includeUncontrolled:true});const existing=windows.find(c=>c.url.startsWith(self.registration.scope));if(existing){await existing.navigate(url.href);await existing.focus()}else await self.clients.openWindow(url.href)})())});
self.addEventListener('message',event=>{if(event.data?.type==='upu-push-clear')event.waitUntil(self.registration.getNotifications().then(ns=>ns.forEach(n=>n.close())))});
